let serviceFilter='all',serviceQuery='';
function renderServiceTasks(){const h=$('#v34ServiceTasks');if(!h)return;const a=serviceTasks.filter(t=>(serviceFilter==='all'||t.kind.toLowerCase()===serviceFilter)&&(!serviceQuery||`${t.title} ${t.detail} ${t.owner}`.toLowerCase().includes(serviceQuery)));h.innerHTML=a.map(t=>`<div class="v34-priority ${t.severity}" data-service-task="${t.id}"><i></i><span><strong>${esc(t.title)}</strong><small>${esc(t.detail)} · Owner ${esc(t.owner)}</small></span><em><b>${esc(t.due)}</b><small>${esc(t.kind)}</small></em></div>`).join('')||'<div class="v33-empty">No service work matches this view.</div>';$$('[data-service-task]',h).forEach(x=>x.onclick=()=>openServiceTask(x.dataset.serviceTask))}
function renderRelationships(){const h=$('#v34Relationships');if(!h)return;const a=serviceRelationships.filter(r=>!serviceQuery||`${r.name} ${r.type} ${r.owner} ${r.id}`.toLowerCase().includes(serviceQuery));h.innerHTML=a.map(r=>`<div class="v34-rel-card" data-service-rel="${r.id}"><div class="v34-rel-avatar">${initials(r.name)}</div><span><strong>${esc(r.name)}</strong><small>${esc(r.id)} · ${esc(r.type)} · ${esc(r.owner)}</small></span><em><b>${esc(r.next)}</b><small>${esc(r.due)} · ${esc(r.portal)}</small></em></div>`).join('');$$('[data-service-rel]',h).forEach(x=>x.onclick=()=>openRelationship(x.dataset.serviceRel))}
function openServiceTask(id){const t=serviceTasks.find(x=>x.id===id);if(!t)return;openModal({eyebrow:`INVESTOR SERVICES · ${esc(t.kind)}`,title:esc(t.title),subtitle:`${esc(t.id)} · owner ${esc(t.owner)} · ${esc(t.due)}`,body:`<div class="v34-grid"><section class="v34-card v34-span-7"><div class="v34-card-head"><div><div class="v34-kicker">NEXT ACTION</div><h2>Complete the service obligation</h2><p>${esc(t.detail)}</p></div></div><div class="v34-card-body"><div class="v34-list"><div class="v34-row"><span><strong>Relationship / fund context</strong><small>Linked records are opened from the client or fund master.</small></span><em>Controlled</em></div><div class="v34-row"><span><strong>Evidence required</strong><small>Approved notice, cash evidence, signature or KYC record according to task type.</small></span><em>Required</em></div><div class="v34-row"><span><strong>Release authority</strong><small>Maker/checker applies to cash movement and client publication.</small></span><em>Human</em></div></div></div></section><aside class="v34-card v34-span-5"><div class="v34-card-head"><div><div class="v34-kicker">SERVICE CONTROL</div><h2>Status</h2></div></div><div class="v34-card-body"><div class="v34-form"><label class="v34-field"><span>Owner</span><select class="v34-select"><option>${esc(t.owner)}</option><option>Client Services</option><option>Fund Ops</option></select></label><label class="v34-field"><span>State</span><select class="v34-select"><option>In progress</option><option>Waiting client</option><option>Ready for checker</option></select></label><label class="v34-field v34-wide"><span>Work note</span><textarea class="v34-textarea" placeholder="Record what was done and the supporting evidence."></textarea></label></div><button class="v34-btn primary" style="width:100%;margin-top:10px" onclick="document.querySelector('#v34Modal .v34-modal-close').click()">Save service update</button></div></aside></div>`})}
function openRelationship(id){const r=serviceRelationships.find(x=>x.id===id);if(!r)return;openModal({eyebrow:'INVESTOR 360 · SERVICE CONTEXT',title:esc(r.name),subtitle:`${esc(r.id)} · ${esc(r.type)} · relationship owner ${esc(r.owner)}`,wide:true,body:`<div class="v34-kpis" style="grid-template-columns:repeat(5,minmax(0,1fr));margin-bottom:12px"><article class="v34-kpi"><span>Relationship value</span><strong>${esc(r.value)}</strong><small>Controlled client view</small></article><article class="v34-kpi"><span>Commitment</span><strong>${esc(r.commitment)}</strong><small>Private capital where applicable</small></article><article class="v34-kpi"><span>Unfunded</span><strong>${esc(r.unfunded)}</strong><small>Remaining commitment</small></article><article class="v34-kpi"><span>Portal</span><strong>${esc(r.portal)}</strong><small>Entitlement state</small></article><article class="v34-kpi"><span>Next obligation</span><strong>${esc(r.next)}</strong><small>${esc(r.due)}</small></article></div><div class="v34-tabs"><button class="active">Overview</button><button>Money</button><button>Publications</button><button>KYC & access</button><button>Messages</button><button>Audit</button></div><div class="v34-grid" style="margin-top:12px"><section class="v34-card v34-span-7"><div class="v34-card-head"><div><div class="v34-kicker">SERVICE PLAN</div><h2>What happens next</h2></div></div><div class="v34-card-body"><div class="v34-list"><div class="v34-row"><span><strong>${esc(r.next)}</strong><small>The workbench routes the task to the responsible team while preserving client context.</small></span><span class="v34-chip warn">${esc(r.due)}</span></div><div class="v34-row"><span><strong>Latest approved statement</strong><small>31 Jul 2026 · released to entitled portal users</small></span><em>Current</em></div><div class="v34-row"><span><strong>Open service requests</strong><small>Secure message and operational cases</small></span><em>${r.id==='CL-00418'?'2':'1'}</em></div></div></div></section><aside class="v34-card v34-span-5"><div class="v34-card-head"><div><div class="v34-kicker">RELATIONSHIP CONTROLS</div><h2>Release gates</h2></div></div><div class="v34-card-body"><div class="v34-list"><div class="v34-row"><span><strong>KYC current</strong></span><em>${r.portal==='Restricted'?'Review':'Yes'}</em></div><div class="v34-row"><span><strong>Bank instructions verified</strong></span><em>Yes</em></div><div class="v34-row"><span><strong>Portal entitlement</strong></span><em>${esc(r.portal)}</em></div></div></div></aside></div>`})}
function buildInvestorServices(){const page=$('#page-investor-services');if(!page)return;page.className='page v33-workspace';page.innerHTML=`<div class="v33-shell v34-service-shell"><header class="v33-head"><div><div class="v33-eyebrow">RELATIONSHIPS · MONEY · PUBLICATIONS · REQUESTS · PORTAL ACCESS</div><h1>Investor Services</h1><p>Start with the investor or the work item. The service desk shows the next human action, the client context, money movement, documents and access status without making teams hunt across modules.</p></div><div class="v33-actions"><button class="v33-btn" id="v34ServicePortal">Investor portal</button><button class="v33-btn" id="v34ServiceMessage">New secure message</button><button class="v33-btn primary" id="v34ServiceTask">+ Service request</button></div></header><div class="v34-kpis"><article class="v34-kpi"><span>Needs action today</span><strong>7</strong><small>3 money · 2 docs · 2 KYC/access</small></article><article class="v34-kpi"><span>Money due in</span><strong>US$ 2.34m</strong><small>17 investor obligations</small></article><article class="v34-kpi"><span>Money due out</span><strong>US$ 712k</strong><small>4 releases awaiting checker</small></article><article class="v34-kpi"><span>Publication queue</span><strong>7</strong><small>2 need signature</small></article><article class="v34-kpi"><span>Open requests</span><strong>12</strong><small>91% within SLA</small></article><article class="v34-kpi alert"><span>Service risk</span><strong>3</strong><small>1 SLA · 2 KYC/access</small></article></div><div class="v34-service-primary"><section class="v34-card"><div class="v34-card-head"><div><div class="v34-kicker">MY WORK</div><h2>What needs attention next</h2><p>One prioritised queue across capital activity, requests, publications, signatures and access.</p></div><div class="v34-search" style="max-width:260px"><input id="v34ServiceSearch" placeholder="Search work or investor"></div></div><div class="v34-card-body"><div class="v34-service-filters" id="v34ServiceFilters"><button class="active" data-sf="all">All</button><button data-sf="money">Money</button><button data-sf="publication">Publications</button><button data-sf="request">Requests</button><button data-sf="signature">Signatures</button><button data-sf="kyc">KYC / access</button></div><div id="v34ServiceTasks" class="v34-priority-list" style="margin-top:5px"></div></div></section><aside class="v34-card"><div class="v34-card-head"><div><div class="v34-kicker">QUICK ACTIONS</div><h2>Common service jobs</h2><p>Open the right workflow directly.</p></div></div><div class="v34-card-body"><div class="v34-list"><div class="v34-row clickable" data-service-nav="onboarding"><span><strong>Review KYC / access restriction</strong><small>Client evidence, screening and activation</small></span><em>Open →</em></div><div class="v34-row clickable" data-service-nav="reports"><span><strong>Publish investor report</strong><small>Approved report → entitled recipients</small></span><em>Open →</em></div><div class="v34-row clickable" id="v34CapitalCall"><span><strong>Create capital call / distribution</strong><small>Amount, LP allocation, notice, cash matching</small></span><em>Start →</em></div><div class="v34-row clickable" data-service-nav="vault"><span><strong>Find client document</strong><small>Mandate, signature, tax or correspondence</small></span><em>Open →</em></div></div></div></aside></div><section class="v34-card"><div class="v34-card-head"><div><div class="v34-kicker">RELATIONSHIPS</div><h2>Investor 360 without losing service context</h2><p>Click any relationship to see money, publications, access and the next obligation.</p></div><button class="v34-btn" id="v34NewInvestor">+ Investor</button></div><div id="v34Relationships"></div></section></div>`;renderServiceTasks();renderRelationships();$('#v34ServiceSearch').oninput=e=>{serviceQuery=e.target.value.toLowerCase();renderServiceTasks();renderRelationships()};$$('[data-sf]',page).forEach(b=>b.onclick=()=>{serviceFilter=b.dataset.sf;$$('[data-sf]',page).forEach(x=>x.classList.toggle('active',x===b));renderServiceTasks()});$$('[data-service-nav]',page).forEach(x=>x.onclick=()=>nav(x.dataset.serviceNav));$('#v34ServicePortal').onclick=()=>{try{window.open('client-portal.html','_blank')}catch(e){notify('Investor portal','Open client-portal.html from the deployment folder.')}};$('#v34ServiceMessage').onclick=()=>openModal({eyebrow:'SECURE COMMUNICATION',title:'New investor message',subtitle:'Client-entitled message with a retained audit record.',body:`<div class="v34-form"><label class="v34-field"><span>Investor</span><select class="v34-select">${serviceRelationships.map(r=>`<option>${esc(r.name)}</option>`).join('')}</select></label><label class="v34-field"><span>Category</span><select class="v34-select"><option>Service update</option><option>Capital event</option><option>Document request</option></select></label><label class="v34-field v34-wide"><span>Message</span><textarea class="v34-textarea"></textarea></label></div>`,footer:`<span></span><div><button class="v34-btn" onclick="document.querySelector('#v34Modal .v34-modal-close').click()">Cancel</button><button class="v34-btn primary" onclick="document.querySelector('#v34Modal .v34-modal-close').click()">Save draft</button></div>`});$('#v34ServiceTask').onclick=()=>openServiceRequest();$('#v34NewInvestor').onclick=()=>nav('onboarding');$('#v34CapitalCall').onclick=()=>openCapitalEvent()}
function openServiceRequest(){openModal({eyebrow:'INVESTOR SERVICES · REQUEST',title:'Create service request',subtitle:'Capture the client need, deadline and accountable owner.',body:`<div class="v34-form"><label class="v34-field"><span>Investor</span><select class="v34-select">${serviceRelationships.map(r=>`<option>${esc(r.name)}</option>`).join('')}</select></label><label class="v34-field"><span>Request type</span><select class="v34-select"><option>Statement / reporting</option><option>Withdrawal / cash</option><option>Bank detail change</option><option>KYC / profile update</option><option>Fee query</option><option>Portal access</option><option>Other</option></select></label><label class="v34-field"><span>Priority</span><select class="v34-select"><option>Normal</option><option>High</option><option>Urgent</option></select></label><label class="v34-field"><span>Due</span><input class="v34-input" type="datetime-local"></label><label class="v34-field v34-wide"><span>Request details</span><textarea class="v34-textarea"></textarea></label></div>`,footer:`<span></span><div><button class="v34-btn" onclick="document.querySelector('#v34Modal .v34-modal-close').click()">Cancel</button><button class="v34-btn primary" id="v34SaveRequest">Create request</button></div>`});$('#v34SaveRequest').onclick=()=>{closeModal();notify('Service request created','Reference and SLA were started and the task was assigned to Investor Services.')}}
function openCapitalEvent(){openModal({eyebrow:'PRIVATE CAPITAL · CONTROLLED EVENT',title:'Create capital event',subtitle:'Call, distribution or subscription with allocation, notice and cash matching controls.',body:`<div class="v34-form-3"><label class="v34-field"><span>Vehicle</span><select class="v34-select"><option>Growth Fund I</option><option>Private Credit Fund I</option></select></label><label class="v34-field"><span>Event</span><select class="v34-select"><option>Capital call</option><option>Distribution</option><option>Subscription</option><option>Redemption</option></select></label><label class="v34-field"><span>Currency</span><select class="v34-select"><option>USD</option><option>ZWG</option></select></label><label class="v34-field"><span>Gross amount</span><input class="v34-input" type="number" value="1000000"></label><label class="v34-field"><span>Notice date</span><input class="v34-input" type="date" value="2026-09-01"></label><label class="v34-field"><span>Due / payment date</span><input class="v34-input" type="date" value="2026-09-07"></label><label class="v34-field v34-wide"><span>Allocation basis and narrative</span><textarea class="v34-textarea">Allocate pro-rata to current unfunded commitments; exclude closed/transferred interests.</textarea></label></div><div class="v34-help" style="margin-top:10px">Workflow: validate LP population → calculate allocation → maker review → checker approval → publish notice → match bank receipts / payments.</div>`,footer:`<span></span><div><button class="v34-btn" onclick="document.querySelector('#v34Modal .v34-modal-close').click()">Cancel</button><button class="v34-btn primary" onclick="document.querySelector('#v34Modal .v34-modal-close').click()">Create controlled draft</button></div>`})}

