let reportFilters={q:'',type:'All',status:'All',owner:'All',from:'2026-08-02',to:'2026-08-31',sort:'updated-desc',preset:'30D'};
function reportRowsFiltered(){let a=reportData.filter(r=>{const d=r.updated.slice(0,10);return (reportFilters.type==='All'||r.type===reportFilters.type)&&(reportFilters.status==='All'||r.status===reportFilters.status)&&(reportFilters.owner==='All'||r.owner===reportFilters.owner)&&(!reportFilters.q||Object.values(r).join(' ').toLowerCase().includes(reportFilters.q))&&(!reportFilters.from||d>=reportFilters.from)&&(!reportFilters.to||d<=reportFilters.to)});a.sort((x,y)=>reportFilters.sort==='updated-desc'?y.updated.localeCompare(x.updated):reportFilters.sort==='updated-asc'?x.updated.localeCompare(y.updated):reportFilters.sort==='title-asc'?x.title.localeCompare(y.title):reportFilters.sort==='title-desc'?y.title.localeCompare(x.title):x.status.localeCompare(y.status));return a}
function renderReportDashboard(){const a=reportRowsFiltered(),k=$('#v34ReportKpis');if(k){const counts={Published:a.filter(x=>x.status==='Published').length,Review:a.filter(x=>x.status==='Review').length,Draft:a.filter(x=>x.status==='Draft').length,Investor:a.filter(x=>x.type==='Investor').length,Regulatory:a.filter(x=>x.type==='Regulatory').length};k.innerHTML=`<article class="v34-kpi"><span>Reports in view</span><strong>${a.length}</strong><small>${reportFilters.from||'Start'} → ${reportFilters.to||'Latest'}</small></article><article class="v34-kpi"><span>Published</span><strong>${counts.Published}</strong><small>Approved outputs</small></article><article class="v34-kpi"><span>Awaiting review</span><strong>${counts.Review}</strong><small>Human sign-off required</small></article><article class="v34-kpi"><span>Draft</span><strong>${counts.Draft}</strong><small>Work in progress</small></article><article class="v34-kpi"><span>Investor reports</span><strong>${counts.Investor}</strong><small>Client-facing outputs</small></article><article class="v34-kpi"><span>Regulatory</span><strong>${counts.Regulatory}</strong><small>Controlled filing packs</small></article>`}const types=['Investor','Investment committee','Risk','Management','Regulatory'],counts=types.map(t=>a.filter(r=>r.type===t).length),max=Math.max(1,...counts),chart=$('#v34ReportChart');if(chart)chart.innerHTML=types.map((t,i)=>`<div class="v34-chart-col"><div class="v34-chart-barwrap"><div class="v34-chart-bar" style="height:${Math.max(4,counts[i]/max*100)}%"><b>${counts[i]}</b></div></div><span title="${esc(t)}">${esc(t.replace('Investment committee','IC'))}</span></div>`).join('');const body=$('#v34ReportRows');if(body)body.innerHTML=a.map(r=>`<tr data-v34-report="${r.id}"><td data-label="Report"><strong>${esc(r.title)}</strong><small>${r.id}</small></td><td data-label="Type">${esc(r.type)}</td><td data-label="Audience">${esc(r.audience)}</td><td data-label="Owner">${esc(r.owner)}</td><td data-label="Updated">${esc(r.updated)}</td><td data-label="Status"><span class="v34-chip ${r.status==='Published'?'good':r.status==='Review'?'warn':'blue'}">${r.status}</span></td></tr>`).join('')||'<tr><td colspan="6"><div class="v33-empty">No reports match the selected date and filters.</div></td></tr>';$$('[data-v34-report]',body||document).forEach(r=>r.onclick=()=>openReportV34(r.dataset.v34Report));$('#v34ReportCount')?.replaceChildren(document.createTextNode(`${a.length} result${a.length===1?'':'s'}`))}
function setReportPreset(p){const end=new Date('2026-08-31T12:00:00'),start=new Date(end);if(p==='7D')start.setDate(end.getDate()-6);else if(p==='30D')start.setDate(end.getDate()-29);else if(p==='MTD')start.setDate(1);else if(p==='QTD'){const q=Math.floor(end.getMonth()/3)*3;start.setMonth(q,1)}else if(p==='YTD')start.setMonth(0,1);else{reportFilters.from='';reportFilters.to='';reportFilters.preset='ALL';syncReportInputs();renderReportDashboard();return}const iso=d=>d.toISOString().slice(0,10);reportFilters.from=iso(start);reportFilters.to=iso(end);reportFilters.preset=p;syncReportInputs();renderReportDashboard()}
function syncReportInputs(){if($('#v34DateFrom'))$('#v34DateFrom').value=reportFilters.from;if($('#v34DateTo'))$('#v34DateTo').value=reportFilters.to;$$('[data-report-preset]').forEach(b=>b.classList.toggle('active',b.dataset.reportPreset===reportFilters.preset))}
function openReportV34(id){const r=reportData.find(x=>x.id===id),host=$('#v34ReportPreview');if(!r||!host)return;host.hidden=false;host.innerHTML=`<div class="v34-report-paper"><div class="v34-kicker">${esc(r.type)} · CONTROLLED OUTPUT</div><h1>${esc(r.title)}</h1><p style="font-size:10px;color:#708096;margin:0">${esc(r.audience)} · ${esc(r.updated)} · owner ${esc(r.owner)} · ${esc(r.id)}</p><div class="v34-paper-metrics"><div><span>Portfolio value</span><strong>US$ 84.62m</strong><small>PBOR / NAV</small></div><div><span>YTD return</span><strong>12.84%</strong><small>Net TWR</small></div><div><span>Benchmark</span><strong>10.74%</strong><small>Approved composite</small></div><div><span>Active return</span><strong>+2.10%</strong><small>Net of fees</small></div></div><h2>Executive summary</h2><p style="font-size:11px;line-height:1.6;color:#354255">The reporting period remained within the approved mandate. Performance, risk and operational outputs are populated from governed portfolio records and remain subject to the report's publication state.</p><h2>Source & governance</h2><table style="width:100%;border-collapse:collapse;font-size:10px"><tr><td style="padding:7px;border-bottom:1px solid #e7ecf2"><strong>Authoritative data</strong></td><td style="padding:7px;border-bottom:1px solid #e7ecf2">PBOR · NAV · risk run · client master</td></tr><tr><td style="padding:7px;border-bottom:1px solid #e7ecf2"><strong>Owner</strong></td><td style="padding:7px;border-bottom:1px solid #e7ecf2">${esc(r.owner)}</td></tr><tr><td style="padding:7px;border-bottom:1px solid #e7ecf2"><strong>Publication state</strong></td><td style="padding:7px;border-bottom:1px solid #e7ecf2">${esc(r.status)}</td></tr><tr><td style="padding:7px"><strong>As-of</strong></td><td style="padding:7px">${esc(r.updated)}</td></tr></table><div style="display:flex;gap:7px;justify-content:flex-end;margin-top:18px"><button class="v34-btn" id="v34ClosePreview">Close preview</button><button class="v34-btn primary" id="v34ExportOne">Export PDF package</button></div></div>`;$('#v34ClosePreview').onclick=()=>{host.hidden=true};$('#v34ExportOne').onclick=()=>notify('Report package prepared','Production export would generate the approved PDF and evidence manifest.') ;host.scrollIntoView({behavior:'smooth',block:'start'})}
function buildReports(){const page=$('#page-reports');if(!page)return;const owners=['All',...new Set(reportData.map(r=>r.owner))];page.innerHTML=`<div class="v33-shell"><header class="v33-head"><div><div class="v33-eyebrow">REPORTS · BI · CONTROLLED PUBLICATION · DATE-AWARE ANALYTICS</div><h1>Reports & BI</h1><p>Filter the actual reporting population by date, type, status and owner. KPI counts and BI summaries recalculate from the same working set; row clicks open the report in place.</p></div><div class="v33-actions"><button class="v33-btn" id="v34ReportExport">Export register</button><button class="v33-btn" id="v34ReportSchedule">Schedules</button><button class="v33-btn primary" id="v34NewReport">+ Report</button></div></header><div class="v34-kpis" id="v34ReportKpis"></div><section class="v34-card"><div class="v34-card-head"><div><div class="v34-kicker">WORKING VIEW</div><h2>Report library</h2><p>Dates are real controls—not decorative filters.</p></div><strong id="v34ReportCount" style="font-size:10px;color:#6d7d92"></strong></div><div class="v34-card-body"><div class="v34-report-filterbar"><div class="v34-search"><input id="v34ReportSearch" placeholder="Search report, portfolio, audience or owner"></div><select class="v34-select" id="v34ReportType"><option>All</option>${['Investor','Investment committee','Risk','Management','Regulatory'].map(x=>`<option>${x}</option>`).join('')}</select><select class="v34-select" id="v34ReportStatus"><option>All</option><option>Published</option><option>Review</option><option>Draft</option></select><select class="v34-select" id="v34ReportOwner">${owners.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="v34-datebar"><label class="v34-field"><span>Updated from</span><input class="v34-input" type="date" id="v34DateFrom"></label><label class="v34-field"><span>Updated to</span><input class="v34-input" type="date" id="v34DateTo"></label><div class="v34-presets">${['7D','30D','MTD','QTD','YTD','ALL'].map(x=>`<button type="button" data-report-preset="${x}">${x}</button>`).join('')}</div><select class="v34-select" id="v34ReportSort" style="max-width:150px"><option value="updated-desc">Updated ↓</option><option value="updated-asc">Updated ↑</option><option value="title-asc">Title A–Z</option><option value="title-desc">Title Z–A</option><option value="status">Status</option></select></div></div></section><div class="v34-report-dashboard"><section class="v34-card"><div class="v34-card-head"><div><div class="v34-kicker">BI SUMMARY</div><h2>Outputs by type</h2><p>Recalculates from the date-filtered report set.</p></div></div><div class="v34-card-body"><div class="v34-chart-bars" id="v34ReportChart"></div></div></section><aside class="v34-card"><div class="v34-card-head"><div><div class="v34-kicker">PUBLICATION CONTROL</div><h2>What can block a report</h2></div></div><div class="v34-card-body"><div class="v34-list"><div class="v34-row"><span><strong>NAV / performance</strong><small>Official period must be locked</small></span><em>Current</em></div><div class="v34-row"><span><strong>Data quality</strong><small>One material exception</small></span><em>1 review</em></div><div class="v34-row"><span><strong>Human reviewer</strong><small>Required for client/regulatory release</small></span><em>Enforced</em></div></div></div></aside></div><section class="v34-card"><div style="overflow:auto"><table class="v34-report-table"><thead><tr><th>Report</th><th>Type</th><th>Audience</th><th>Owner</th><th>Updated</th><th>Status</th></tr></thead><tbody id="v34ReportRows"></tbody></table></div></section><section class="v34-report-preview" id="v34ReportPreview" hidden></section></div>`;syncReportInputs();renderReportDashboard();$('#v34ReportSearch').oninput=e=>{reportFilters.q=e.target.value.toLowerCase();renderReportDashboard()};$('#v34ReportType').onchange=e=>{reportFilters.type=e.target.value;renderReportDashboard()};$('#v34ReportStatus').onchange=e=>{reportFilters.status=e.target.value;renderReportDashboard()};$('#v34ReportOwner').onchange=e=>{reportFilters.owner=e.target.value;renderReportDashboard()};$('#v34ReportSort').onchange=e=>{reportFilters.sort=e.target.value;renderReportDashboard()};$('#v34DateFrom').onchange=e=>{reportFilters.from=e.target.value;reportFilters.preset='';syncReportInputs();renderReportDashboard()};$('#v34DateTo').onchange=e=>{reportFilters.to=e.target.value;reportFilters.preset='';syncReportInputs();renderReportDashboard()};$$('[data-report-preset]',page).forEach(b=>b.onclick=()=>setReportPreset(b.dataset.reportPreset));$('#v34ReportExport').onclick=()=>{const a=reportRowsFiltered();csvDownload('matanho-report-register.csv',[['ID','Title','Type','Audience','Owner','Updated','Status'],...a.map(r=>[r.id,r.title,r.type,r.audience,r.owner,r.updated,r.status])]);notify('Report register exported',`${a.length} filtered rows exported.`)};$('#v34ReportSchedule').onclick=()=>notify('Report schedules','Schedule manager would show recurring report generation and publication windows.');$('#v34NewReport').onclick=()=>openModal({eyebrow:'REPORT DEFINITION',title:'Create report',subtitle:'Define audience, period, authoritative inputs and publication authority.',body:`<div class="v34-form"><label class="v34-field"><span>Report title</span><input class="v34-input"></label><label class="v34-field"><span>Type</span><select class="v34-select"><option>Investor</option><option>Investment committee</option><option>Risk</option><option>Management</option><option>Regulatory</option></select></label><label class="v34-field"><span>Audience</span><input class="v34-input"></label><label class="v34-field"><span>Frequency</span><select class="v34-select"><option>Monthly</option><option>Quarterly</option><option>Ad hoc</option></select></label><label class="v34-field v34-wide"><span>Authoritative data products</span><textarea class="v34-textarea" placeholder="PBOR, NAV, risk run, client master…"></textarea></label></div>`,footer:`<span></span><div><button class="v34-btn" onclick="document.querySelector('#v34Modal .v34-modal-close').click()">Cancel</button><button class="v34-btn primary" onclick="document.querySelector('#v34Modal .v34-modal-close').click()">Create draft</button></div>`})}

