let reconMode='exception',reconFamily='All',reconQuery='',reconSelected='REC-66102',reconTab='compare';
function reconFiltered(){return reconRecords.filter(r=>r.mode===reconMode&&(reconFamily==='All'||r.family===reconFamily)&&(!reconQuery||`${r.id} ${r.family} ${r.record} ${r.owner}`.toLowerCase().includes(reconQuery)))}
function renderReconList(){const h=$('#v34ReconList');if(!h)return;const a=reconFiltered();if(!a.some(x=>x.id===reconSelected)&&a[0])reconSelected=a[0].id;h.innerHTML=a.map(r=>`<div class="v34-recon-item ${r.mode==='match'?'match':''} ${r.severity==='Critical'?'critical':''} ${r.id===reconSelected?'active':''}" data-v34-recon="${r.id}"><i></i><span><strong>${esc(r.family)} · ${esc(r.record)}</strong><small>${r.id} · ${r.mode==='match'?'matched automatically':`${r.age.toFixed(1)}d · owner ${esc(r.owner)}`}</small></span><em>${esc(r.diff)}<small>${r.confidence}%</small></em></div>`).join('')||'<div class="v33-empty">No records match this view.</div>';$$('[data-v34-recon]',h).forEach(x=>x.onclick=()=>{reconSelected=x.dataset.v34Recon;reconTab='compare';renderReconList();renderReconDetail()})}
function sourceCard(ref,title){const s=sourceRegistry[ref];if(!s)return'';return `<section class="v34-source"><div class="v34-source-head"><div><div class="v34-kicker">${esc(title)}</div><strong>${esc(s.system)}</strong></div><span class="v34-chip ${s.status==='Current'?'good':'warn'}">${esc(s.kind)}</span></div><dl><dt>Source object</dt><dd>${esc(s.name)}</dd><dt>Run / reference</dt><dd>${esc(s.ref)}</dd><dt>Received</dt><dd>${esc(s.received)}</dd><dt>Record locator</dt><dd>${esc(s.locator)}</dd><dt>Integrity</dt><dd><span class="v34-code">${esc(s.hash)}</span></dd></dl></section>`}
function renderReconDetail(){const r=reconRecords.find(x=>x.id===reconSelected),h=$('#v34ReconDetail');if(!h||!r)return;h.innerHTML=`<div class="v34-card-head"><div><div class="v34-kicker">${r.id} · ${esc(r.family)}</div><h2 style="font-size:18px">${esc(r.record)}</h2><p>${r.mode==='match'?'Automatically matched and retained with source lineage.':`${r.age.toFixed(1)} days · owner ${esc(r.owner)} · ${esc(r.state)}`}</p></div><span class="v34-chip ${r.mode==='match'?'good':r.severity==='Critical'?'bad':'warn'}">${esc(r.mode==='match'?'Matched':r.severity)}</span></div><div class="v34-card-body"><div class="v34-tabs"><button class="${reconTab==='compare'?'active':''}" data-recon-tab="compare">Compare</button><button class="${reconTab==='source'?'active':''}" data-recon-tab="source">Source & lineage</button><button class="${reconTab==='rules'?'active':''}" data-recon-tab="rules">Matching rules</button>${r.mode==='exception'?`<button class="${reconTab==='resolve'?'active':''}" data-recon-tab="resolve">Resolve & approve</button>`:''}</div><div id="v34ReconPane" style="margin-top:12px"></div></div>`;$$('[data-recon-tab]',h).forEach(b=>b.onclick=()=>{reconTab=b.dataset.reconTab;renderReconDetail()});renderReconPane(r)}
function renderReconPane(r){
  const h=$('#v34ReconPane');
  if(!h)return;
  if(reconTab==='compare'){
    h.innerHTML=`<div class="v34-compare"><div><span>Internal authoritative record</span><strong>${esc(r.internal)}</strong><small>${esc(sourceRegistry[r.internalSource]?.system)} · ${esc(sourceRegistry[r.internalSource]?.ref)}</small></div><div class="delta ${r.mode==='match'?'good':''}"><span>Difference</span><strong>${esc(r.diff)}</strong><small>${r.confidence}% match confidence</small></div><div><span>Independent evidence</span><strong>${esc(r.external)}</strong><small>${esc(sourceRegistry[r.externalSource]?.system)} · ${esc(sourceRegistry[r.externalSource]?.ref)}</small></div></div>${r.mode==='exception'?`<div class="v34-grid" style="margin-top:12px"><section class="v34-card v34-span-7"><div class="v34-card-head"><div><div class="v34-kicker">INVESTIGATION</div><h2>Candidate and cause</h2></div><button class="v34-btn small" id="v34Rematch">Re-run</button></div><div class="v34-card-body"><div class="v34-list"><div class="v34-row"><span><strong>Suggested candidate</strong><small>Candidate came from ${esc(sourceRegistry[r.candidateSource]?.system||'source run')}</small></span><em>${esc(r.candidate)}</em></div><div class="v34-row"><span><strong>Probable cause</strong><small>System suggestion; maker must confirm</small></span><em>${esc(r.cause)}</em></div><div class="v34-row"><span><strong>Recommended action</strong><small>Control playbook</small></span><em>${esc(r.action)}</em></div></div></div></section><aside class="v34-card v34-span-5"><div class="v34-card-head"><div><div class="v34-kicker">SOURCE ANSWER</div><h2>Where did this match come from?</h2></div></div><div class="v34-card-body"><p style="font-size:10.5px;line-height:1.55;color:#435166;margin:0">The internal side is a governed book snapshot. The external side is an independent file/API/feed record. The candidate is produced by the matching rules shown in this record. Open <b>Source & lineage</b> for the exact file/feed reference, received time and record locator.</p></div></aside></div>`:`<div class="v34-card" style="margin-top:12px"><div class="v34-card-body" style="padding-top:15px"><span class="v34-chip good">No human action required</span><p style="font-size:10.5px;color:#536278;line-height:1.55">The match remains auditable even though it is removed from the exception queue. Both source references and the rule result are retained.</p></div></div>`}`;
    $('#v34Rematch')?.addEventListener('click',()=>notify('Matching re-run',`${r.confidence}% candidate retained from the same source population.`));
  } else if(reconTab==='source'){
    h.innerHTML=`<div class="v34-source-grid">${sourceCard(r.internalSource,'INTERNAL SOURCE')}${sourceCard(r.externalSource,'INDEPENDENT SOURCE')}</div>${r.candidateSource&&r.candidateSource!==r.externalSource?`<div style="margin-top:9px">${sourceCard(r.candidateSource,'CANDIDATE SOURCE')}</div>`:''}<div class="v34-card" style="margin-top:10px"><div class="v34-card-head"><div><div class="v34-kicker">PROVENANCE POLICY</div><h2>Evidence that travels with the match</h2><p>Production records should retain source system, immutable batch/reference, received timestamp, record locator, integrity/checksum, parser/schema version and matching-rule version.</p></div></div></div>`;
  } else if(reconTab==='rules'){
    h.innerHTML=`<div class="v34-card"><div class="v34-card-head"><div><div class="v34-kicker">MATCH LOGIC</div><h2>Why the engine linked these records</h2><p>Confidence is explainable; it is not a black-box score.</p></div><span class="v34-chip ${r.confidence>=95?'good':'warn'}">${r.confidence}% confidence</span></div><div class="v34-card-body"><div class="v34-rule-list">${r.rules.map(x=>`<div class="v34-rule"><span><strong>${esc(x[0])}</strong><small>${esc(x[2])}</small></span><em>${esc(x[1])}</em></div>`).join('')}</div></div></div>`;
  } else {
    h.innerHTML=`<div class="v34-grid"><section class="v34-card v34-span-7"><div class="v34-card-head"><div><div class="v34-kicker">MAKER RESOLUTION</div><h2>Explain the cause and correction</h2></div></div><div class="v34-card-body"><div class="v34-form"><label class="v34-field"><span>Root cause</span><select class="v34-select" id="v34ReconCause"><option>${esc(r.cause)}</option><option>Timing difference</option><option>Internal booking error</option><option>External source error</option><option>Reference-data mismatch</option><option>Within tolerance</option></select></label><label class="v34-field"><span>Corrective action</span><select class="v34-select" id="v34ReconAction"><option>${esc(r.action)}</option><option>Post adjustment</option><option>Correct external source</option><option>Accept within tolerance</option><option>Await settlement</option></select></label><label class="v34-field v34-wide"><span>Resolution rationale *</span><textarea class="v34-textarea" id="v34ReconRationale" placeholder="State the evidence reviewed, the cause and the approved correction."></textarea></label></div><button class="v34-btn primary" id="v34ReconMaker" style="width:100%;margin-top:10px" ${r.state==='Pending checker'?'disabled':''}>${r.state==='Pending checker'?'Maker submitted':'Submit maker resolution'}</button></div></section><aside class="v34-card v34-span-5"><div class="v34-card-head"><div><div class="v34-kicker">INDEPENDENT CHECKER</div><h2>Close only after evidence agrees</h2></div></div><div class="v34-card-body"><div class="v34-list"><div class="v34-row"><span><strong>Maker</strong><small>Cannot self-approve</small></span><em>${esc(r.maker||'Not submitted')}</em></div><div class="v34-row"><span><strong>Source lineage</strong><small>Frozen with close</small></span><em>Complete</em></div><div class="v34-row"><span><strong>Checker</strong><small>Independent operations approver</small></span><em>${esc(r.checker||'Required')}</em></div></div><button class="v34-btn" id="v34ReconChecker" style="width:100%;margin-top:10px" ${r.state==='Pending checker'?'':'disabled'}>Approve and close</button></div></aside></div>`;
    const maker=$('#v34ReconMaker');
    if(maker)maker.onclick=()=>{const text=$('#v34ReconRationale').value.trim();if(!text)return notify('Rationale required','The maker must document the evidence and correction.','error');r.state='Pending checker';r.maker='T. Moyo';r.resolution=text;notify('Maker resolution submitted','An independent checker is now required.');renderReconDetail()};
    const checker=$('#v34ReconChecker');
    if(checker)checker.onclick=()=>{r.state='Closed';r.checker='N. Dube';r.mode='match';r.diff='0 / resolved';r.confidence=100;r.severity='Matched';notify('Reconciliation closed',`${r.id} moved out of the exception queue with frozen evidence.`);renderReconAll()};
  }
}
function renderReconAll(){renderReconKpis();renderReconList();renderReconDetail()}
function renderReconKpis(){const exc=reconRecords.filter(r=>r.mode==='exception'),matches=reconRecords.filter(r=>r.mode==='match'),total=exc.length+matches.length,rate=total?matches.length/total*100:100;const h=$('#v34ReconKpis');if(h)h.innerHTML=`<article class="v34-kpi"><span>Matched population</span><strong>${matches.length}</strong><small>Traceable automatic / closed matches</small></article><article class="v34-kpi"><span>Open breaks</span><strong>${exc.length}</strong><small>${exc.filter(x=>x.severity==='Critical'||x.severity==='High').length} material</small></article><article class="v34-kpi"><span>Match rate</span><strong>${rate.toFixed(1)}%</strong><small>Demo population shown here</small></article><article class="v34-kpi"><span>Source runs</span><strong>${Object.keys(sourceRegistry).length}</strong><small>File · API · feed · ledger</small></article><article class="v34-kpi"><span>Oldest break</span><strong>${Math.max(0,...exc.map(x=>x.age)).toFixed(1)}d</strong><small>Material ageing</small></article><article class="v34-kpi ${exc.some(x=>x.severity==='Critical')?'alert':''}"><span>Daily sign-off</span><strong>${exc.some(x=>x.severity==='Critical')?'Blocked':'Ready'}</strong><small>${exc.some(x=>x.severity==='Critical')?'Critical break open':'Checker can sign off'}</small></article>`}
function buildReconciliations(){const page=$('#page-reconciliations');if(!page)return;page.innerHTML=`<div class="v33-shell"><header class="v33-head"><div><div class="v33-eyebrow">LOAD SOURCES → MATCH → EXCEPTIONS → MAKER → CHECKER → SIGN-OFF</div><h1>Reconciliations</h1><p>Trade and cash reconciliation now shows exactly which internal book and independent file/API/feed produced each match. Routine matches remain searchable; exceptions contain the same source lineage and explainable matching rules.</p></div><div class="v33-actions"><button class="v33-btn" id="v34ReconSources">Source runs</button><button class="v33-btn" id="v34ReconImport">Import statement / file</button><button class="v33-btn primary" id="v34ReconRun">Run reconciliation</button></div></header><div class="v34-kpis" id="v34ReconKpis"></div><div class="v34-recon-source-banner"><div><strong>Every result has provenance.</strong><small>Internal: IBOR/ABOR/unit register. Independent: bank API/statement, broker FIX/contract note, custodian/TA file. File name or feed reference, received time, record locator and integrity reference remain attached.</small></div><span class="v34-chip blue">V34 source-aware</span></div><div class="v34-recon-workflow"><div class="done"><span>01</span><strong>Load sources</strong></div><div class="done"><span>02</span><strong>Validate & normalise</strong></div><div class="done"><span>03</span><strong>Auto-match</strong></div><div class="active"><span>04</span><strong>Investigate breaks</strong></div><div><span>05</span><strong>Maker / checker</strong></div><div><span>06</span><strong>Daily sign-off</strong></div></div><div class="v34-toolbar"><div class="v34-recon-mode"><button class="active" data-recon-mode="exception">Exceptions</button><button data-recon-mode="match">Matched</button></div><div class="v34-tabs" id="v34ReconFamilies">${['All','Cash','Holdings','Trades','Settlement','Units'].map((x,i)=>`<button class="${i===0?'active':''}" data-recon-family="${x}">${x}</button>`).join('')}</div></div><div class="v34-recon-layout"><aside class="v34-card"><div class="v34-card-head"><div><div class="v34-kicker" id="v34ReconQueueKicker">EXCEPTION QUEUE</div><h2 id="v34ReconQueueTitle">Only genuine differences</h2></div></div><div class="v34-card-body"><div class="v34-search"><input id="v34ReconSearch" placeholder="Search record, source or owner"></div></div><div class="v34-recon-list" id="v34ReconList"></div></aside><main class="v34-card" id="v34ReconDetail"></main></div></div>`;renderReconAll();$$('[data-recon-mode]',page).forEach(b=>b.onclick=()=>{reconMode=b.dataset.reconMode;$$('[data-recon-mode]',page).forEach(x=>x.classList.toggle('active',x===b));$('#v34ReconQueueKicker').textContent=reconMode==='exception'?'EXCEPTION QUEUE':'MATCH REGISTER';$('#v34ReconQueueTitle').textContent=reconMode==='exception'?'Only genuine differences':'Current matches with provenance';const a=reconFiltered();if(a[0])reconSelected=a[0].id;reconTab='compare';renderReconList();renderReconDetail()});$$('[data-recon-family]',page).forEach(b=>b.onclick=()=>{reconFamily=b.dataset.reconFamily;$$('[data-recon-family]',page).forEach(x=>x.classList.toggle('active',x===b));const a=reconFiltered();if(a[0])reconSelected=a[0].id;renderReconList();renderReconDetail()});$('#v34ReconSearch').oninput=e=>{reconQuery=e.target.value.toLowerCase();renderReconList()};$('#v34ReconRun').onclick=()=>{notify('Reconciliation run complete','Source populations validated, matching rules executed and only unresolved differences remain in Exceptions.');renderReconAll()};$('#v34ReconSources').onclick=openSourceRuns;$('#v34ReconImport').onclick=openReconImport}
function openSourceRuns(){openModal({eyebrow:'RECONCILIATION · SOURCE RUNS',title:'Independent evidence and internal populations',subtitle:'This registry answers where each match came from.',wide:true,body:`<div style="overflow:auto"><table class="v34-report-table"><thead><tr><th>Source</th><th>Kind</th><th>Object</th><th>Reference</th><th>Received</th><th>Status</th></tr></thead><tbody>${Object.values(sourceRegistry).map(s=>`<tr><td data-label="Source"><strong>${esc(s.system)}</strong><small>${esc(s.side)}</small></td><td data-label="Kind">${esc(s.kind)}</td><td data-label="Object">${esc(s.name)}</td><td data-label="Reference">${esc(s.ref)}</td><td data-label="Received">${esc(s.received)}</td><td data-label="Status"><span class="v34-chip good">${esc(s.status)}</span></td></tr>`).join('')}</tbody></table></div><p class="v34-help" style="margin-top:10px">In production these rows are created by Data Fabric ingestion jobs and immutable evidence storage—not by hard-coded JavaScript.</p>`})}
function openReconImport(){const m=openModal({eyebrow:'RECONCILIATION · SOURCE INGESTION',title:'Import statement or reconciliation file',subtitle:'Add an independent evidence population. The prototype reads the local file only to show its name and row count; production ingestion requires backend validation, schema controls and evidence storage.',body:`<div class="v34-form"><label class="v34-field"><span>Source / provider</span><input class="v34-input" id="v34ImportProvider" placeholder="Bank / broker / custodian / TA"></label><label class="v34-field"><span>Control family</span><select class="v34-select" id="v34ImportFamily"><option>Cash</option><option>Holdings</option><option>Trades</option><option>Settlement</option><option>Units</option></select></label><label class="v34-field v34-wide"><span>Statement / file *</span><input class="v34-input" type="file" id="v34ImportFile" accept=".csv,.txt,.json"></label><div class="v34-field v34-wide"><span>Local preview</span><div class="v34-code" id="v34ImportPreview">No file selected.</div></div></div>`,footer:`<span></span><div><button class="v34-btn" onclick="document.querySelector('#v34Modal .v34-modal-close').click()">Cancel</button><button class="v34-btn primary" id="v34SaveImport" disabled>Register source run</button></div>`});let fileMeta=null;$('#v34ImportFile',m).onchange=e=>{const f=e.target.files?.[0];if(!f)return;const reader=new FileReader();reader.onload=()=>{const text=String(reader.result||''),lines=text.split(/\r?\n/).filter(Boolean).length;fileMeta={name:f.name,size:f.size,lines};$('#v34ImportPreview',m).textContent=`${f.name} · ${f.size.toLocaleString()} bytes · ${lines} non-empty rows`;$('#v34SaveImport',m).disabled=false};reader.readAsText(f)};$('#v34SaveImport',m).onclick=()=>{const provider=$('#v34ImportProvider',m).value.trim()||'Imported source',id=`SRC-UPL-${Date.now().toString().slice(-6)}`;sourceRegistry[id]={side:'External',kind:'Uploaded file',system:provider,name:fileMeta.name,ref:id,received:new Date().toLocaleString(),locator:`${fileMeta.lines} local rows`,hash:'prototype:file-metadata-only',status:'Current'};closeModal();notify('Source run registered',`${fileMeta.name} is now visible in source lineage. Matching remains a prototype until backend ingestion is connected.`);renderReconKpis()}}

