let kycCases=[
{id:'KYC-2418',name:'Horizon Pension Fund',type:'Institutional',risk:'Medium',owner:'R. Ncube',readiness:96,status:'Ready',blockers:0,next:'Final activation',stage:6,screen:'Clear',provider:'Screening provider · demo',screenRef:'SCR-2418-0831',screened:'31 Aug · 14:22 CAT',decision:'Approved',mandate:'Approved',evidence:[['Entity registration','Applicant upload','DOC-8121','Current'],['Authorised signatories','Applicant upload','DOC-8124','Current'],['Bank confirmation','Bank letter','DOC-8130','Current'],['Mandate / IPS','Client Services','DOC-8132','Current']]},
{id:'KYC-2422',name:'Mupfumi Family Office',type:'Family office',risk:'High',owner:'T. Moyo',readiness:68,status:'Action',blockers:3,next:'Source of wealth evidence',stage:3,screen:'PEP review',provider:'Screening provider · demo',screenRef:'SCR-2422-0831',screened:'31 Aug · 14:08 CAT',decision:'Pending',mandate:'Draft',evidence:[['Identity / legal existence','Applicant upload','DOC-8201','Current'],['Ownership chart','Applicant upload','DOC-8202','Current'],['Source of wealth','Requested','—','Missing'],['Bank source evidence','Applicant upload','DOC-8209','Review']]},
{id:'KYC-2427',name:'Baobab Endowment',type:'Institutional',risk:'Low',owner:'S. Dube',readiness:82,status:'Action',blockers:2,next:'Authorised signatory ID',stage:2,screen:'Clear',provider:'Screening provider · demo',screenRef:'SCR-2427-0831',screened:'31 Aug · 13:58 CAT',decision:'Pending',mandate:'Review',evidence:[['Entity registration','Registry extract','REG-1422','Current'],['Signatory ID','Requested','—','Missing'],['Tax declaration','Applicant upload','DOC-8244','Current'],['Bank confirmation','Bank letter','DOC-8248','Current']]},
{id:'KYC-2431',name:'Nyanga Holdings',type:'Corporate',risk:'Medium',owner:'R. Ncube',readiness:54,status:'Action',blockers:4,next:'Ownership verification',stage:1,screen:'Not run',provider:'Not run',screenRef:'—',screened:'—',decision:'Pending',mandate:'Not started',evidence:[['Entity registration','Applicant upload','DOC-8291','Current'],['Share register','Applicant upload','DOC-8292','Review'],['UBO identity','Requested','—','Missing'],['Bank confirmation','Requested','—','Missing']]}
];
let kycSelected='KYC-2418',kycTab='decision',kycQuery='',kycFilter='action';
const kycStages=['Application','Ownership','Identity','Financial crime','Suitability','Mandate','Approval'];
function kycFiltered(){return kycCases.filter(c=>(kycFilter==='all'||kycFilter==='action'&&c.status!=='Ready'||kycFilter==='ready'&&c.status==='Ready'||kycFilter==='high'&&c.risk==='High')&&(!kycQuery||`${c.name} ${c.id} ${c.owner}`.toLowerCase().includes(kycQuery)))}
function renderKycQueue(){const h=$('#v34KycQueue');if(!h)return;const a=kycFiltered();if(!a.some(x=>x.id===kycSelected)&&a[0])kycSelected=a[0].id;h.innerHTML=a.map(c=>`<div class="v34-kyc-case ${c.id===kycSelected?'active':''}" data-v34-kyc="${c.id}"><div class="v34-kyc-case-top"><span><strong>${esc(c.name)}</strong><small>${c.id} · ${c.type} · ${c.owner}</small></span><span class="v34-chip ${c.status==='Ready'?'good':c.risk==='High'?'bad':'blue'}">${c.status==='Ready'?'Ready':c.risk}</span></div><div class="v34-progress ${c.readiness<70?'warn':''}" style="margin-top:8px"><i style="width:${c.readiness}%"></i></div><small style="margin-top:6px">${c.readiness}% · ${c.blockers} blocker${c.blockers===1?'':'s'} · next: ${esc(c.next)}</small></div>`).join('')||'<div class="v33-empty">No KYC cases match this view.</div>';$$('[data-v34-kyc]',h).forEach(x=>x.onclick=()=>{kycSelected=x.dataset.v34Kyc;kycTab='decision';renderKycQueue();renderKycDetail()})}
function renderKycDetail(){const c=kycCases.find(x=>x.id===kycSelected),h=$('#v34KycDetail');if(!c||!h)return;h.innerHTML=`<div class="v34-card-head"><div><div class="v34-kicker">${c.id} · ${esc(c.type)}</div><h2 style="font-size:18px">${esc(c.name)}</h2><p>${c.readiness}% ready · ${c.blockers} blockers · owner ${esc(c.owner)} · next: ${esc(c.next)}</p></div><span class="v34-chip ${c.status==='Ready'?'good':c.risk==='High'?'bad':'warn'}">${esc(c.status)}</span></div><div class="v34-card-body"><div class="v34-journey">${kycStages.map((s,i)=>`<button class="${i<c.stage?'done':i===c.stage?(c.blockers?'blocked':'active'):''}" data-kyc-stage="${i}"><span>0${i+1}</span><strong>${s}</strong></button>`).join('')}</div><div class="v34-tabs" style="margin-top:12px"><button class="${kycTab==='decision'?'active':''}" data-kyc-tab="decision">Decision brief</button><button class="${kycTab==='parties'?'active':''}" data-kyc-tab="parties">Parties & UBOs</button><button class="${kycTab==='screening'?'active':''}" data-kyc-tab="screening">Screening</button><button class="${kycTab==='evidence'?'active':''}" data-kyc-tab="evidence">Evidence</button><button class="${kycTab==='mandate'?'active':''}" data-kyc-tab="mandate">Suitability & mandate</button><button class="${kycTab==='audit'?'active':''}" data-kyc-tab="audit">Approval & audit</button></div><div id="v34KycPane" style="margin-top:12px"></div></div>`;$$('[data-kyc-tab]',h).forEach(b=>b.onclick=()=>{kycTab=b.dataset.kycTab;renderKycDetail()});$$('[data-kyc-stage]',h).forEach(b=>b.onclick=()=>{const i=+b.dataset.kycStage;kycTab=i<=1?'parties':i===2||i===3?'screening':i<=5?'mandate':'audit';renderKycDetail()});renderKycPane(c)}
function renderKycPane(c){
  const h=$('#v34KycPane');
  if(!h)return;
  if(kycTab==='decision'){
    h.innerHTML=`<div class="v34-grid"><section class="v34-card v34-span-7"><div class="v34-card-head"><div><div class="v34-kicker">WHAT MUST HAPPEN NEXT</div><h2>${esc(c.next)}</h2></div><button class="v34-btn primary" id="v34KycWork">Review now</button></div><div class="v34-card-body"><div class="v34-decision-grid"><div class="v34-decision"><span>Readiness</span><strong>${c.readiness}%</strong><small>${c.blockers} hard blockers</small></div><div class="v34-decision"><span>Financial crime</span><strong>${esc(c.screen)}</strong><small>${esc(c.screenRef)}</small></div><div class="v34-decision"><span>Mandate</span><strong>${esc(c.mandate)}</strong><small>Suitability + dealing permissions</small></div><div class="v34-decision"><span>Human KYC decision</span><strong>${esc(c.decision)}</strong><small>Compliance authority only</small></div></div></div></section><aside class="v34-card v34-span-5"><div class="v34-card-head"><div><div class="v34-kicker">ACTIVATION GATES</div><h2>Why the account can or cannot activate</h2></div></div><div class="v34-card-body"><div class="v34-list"><div class="v34-row"><span><strong>Ownership</strong><small>UBOs + controllers</small></span><em>${c.stage>1?'Complete':'Review'}</em></div><div class="v34-row"><span><strong>Identity / evidence</strong><small>${c.evidence.filter(e=>e[3]==='Missing').length} missing</small></span><em>${c.evidence.filter(e=>e[3]==='Missing').length?'Open':'Complete'}</em></div><div class="v34-row"><span><strong>Screening disposition</strong><small>Provider result + human review</small></span><em>${esc(c.screen)}</em></div><div class="v34-row"><span><strong>Mandate</strong><small>Approved permissions</small></span><em>${esc(c.mandate)}</em></div></div></div></aside></div>`;
    $('#v34KycWork')?.addEventListener('click',()=>{kycTab=c.stage<=1?'parties':c.stage<=3?'screening':c.stage<=5?'mandate':'audit';renderKycDetail()});
  } else if(kycTab==='parties'){
    h.innerHTML=`<div class="v34-grid"><section class="v34-card v34-span-8"><div class="v34-card-head"><div><div class="v34-kicker">LEGAL & BENEFICIAL OWNERSHIP</div><h2>Parties controlling the relationship</h2><p>Ownership must reconcile to 100% or explicitly document why economic ownership is not applicable.</p></div><button class="v34-btn">+ Party</button></div><div style="overflow:auto"><table class="v34-evidence-table"><thead><tr><th>Party</th><th>Role</th><th>Ownership</th><th>ID source</th><th>Screening</th></tr></thead><tbody><tr><td>${esc(c.name)}</td><td>Applicant</td><td>—</td><td>Entity record</td><td>${c.screen==='Not run'?'Pending':'Clear'}</td></tr><tr><td>Tariro Chuma</td><td>Controller / signatory</td><td>35%</td><td>Passport</td><td>${c.risk==='High'?'Review':'Clear'}</td></tr><tr><td>Munashe Trust Co.</td><td>Beneficial owner</td><td>25%</td><td>Trust record</td><td>Clear</td></tr><tr><td>Other declared owners</td><td>Beneficial ownership</td><td>40%</td><td>Ownership register</td><td>Clear</td></tr></tbody></table></div></section><aside class="v34-card v34-span-4"><div class="v34-card-head"><div><div class="v34-kicker">OWNERSHIP CONTROL</div><h2>Completeness</h2></div></div><div class="v34-card-body"><div class="v34-list"><div class="v34-row"><span><strong>Economic ownership</strong></span><em>100%</em></div><div class="v34-row"><span><strong>Controllers</strong></span><em>${c.stage>1?'Complete':'Review'}</em></div><div class="v34-row"><span><strong>Signatory authority</strong></span><em>${c.id==='KYC-2427'?'Missing ID':'Current'}</em></div></div></div></aside></div>`;
  } else if(kycTab==='screening'){
    h.innerHTML=`<div class="v34-grid"><section class="v34-card v34-span-8"><div class="v34-card-head"><div><div class="v34-kicker">IDENTITY · SANCTIONS · PEP · ADVERSE INFORMATION</div><h2>Screening results with source</h2><p>A result is useful only if the provider, run reference, time and human disposition are visible.</p></div><button class="v34-btn" id="v34RefreshKyc">Refresh screening</button></div><div class="v34-card-body"><div class="v34-decision-grid"><div class="v34-decision"><span>Provider / source</span><strong>${esc(c.provider)}</strong><small>Production connector required</small></div><div class="v34-decision"><span>Run reference</span><strong>${esc(c.screenRef)}</strong><small>${esc(c.screened)}</small></div><div class="v34-decision"><span>Sanctions</span><strong>Clear</strong><small>No blocking match in demo result</small></div><div class="v34-decision"><span>PEP / adverse info</span><strong>${esc(c.screen)}</strong><small>Human disposition required for possible matches</small></div></div><div class="v34-form" style="margin-top:10px"><label class="v34-field"><span>Source of funds</span><textarea class="v34-textarea">Operating income / investment proceeds supported by bank evidence.</textarea></label><label class="v34-field"><span>Source of wealth</span><textarea class="v34-textarea">Accumulated business and investment earnings; enhanced evidence where risk requires.</textarea></label><label class="v34-field v34-wide"><span>Human disposition / rationale</span><textarea class="v34-textarea" placeholder="Record why a possible match is cleared or escalated."></textarea></label></div></div></section><aside class="v34-card v34-span-4"><div class="v34-card-head"><div><div class="v34-kicker">RISK FACTORS</div><h2>${esc(c.risk)} risk</h2></div></div><div class="v34-card-body"><div class="v34-list"><div class="v34-row"><span><strong>Jurisdiction</strong></span><em>Zimbabwe</em></div><div class="v34-row"><span><strong>Client type</strong></span><em>${esc(c.type)}</em></div><div class="v34-row"><span><strong>PEP factor</strong></span><em>${c.screen.includes('PEP')?'Present / review':'No match'}</em></div><div class="v34-row"><span><strong>EDD</strong></span><em>${c.risk==='High'?'Required':'Risk-based'}</em></div></div></div></aside></div>`;
    $('#v34RefreshKyc')?.addEventListener('click',()=>{c.provider='Screening provider · demo';c.screenRef=`SCR-${c.id.slice(-4)}-${Date.now().toString().slice(-4)}`;c.screened=new Date().toLocaleString();notify('Screening refreshed','New run reference retained. Final KYC decision remains human.');renderKycDetail()});
  } else if(kycTab==='evidence'){
    h.innerHTML=`<div class="v34-card"><div class="v34-card-head"><div><div class="v34-kicker">CONTROLLED EVIDENCE</div><h2>Documents and source references</h2><p>Every item identifies how it arrived and which control it supports.</p></div><button class="v34-btn">Request evidence</button></div><div style="overflow:auto"><table class="v34-evidence-table"><thead><tr><th>Evidence</th><th>Source</th><th>Reference</th><th>State</th></tr></thead><tbody>${c.evidence.map(e=>`<tr><td>${esc(e[0])}</td><td>${esc(e[1])}</td><td>${esc(e[2])}</td><td><span class="v34-chip ${e[3]==='Current'?'good':e[3]==='Missing'?'bad':'warn'}">${esc(e[3])}</span></td></tr>`).join('')}</tbody></table></div></div>`;
  } else if(kycTab==='mandate'){
    h.innerHTML=`<div class="v34-grid"><section class="v34-card v34-span-7"><div class="v34-card-head"><div><div class="v34-kicker">SUITABILITY & APPROPRIATENESS</div><h2>Investor profile</h2></div></div><div class="v34-card-body"><div class="v34-form"><label class="v34-field"><span>Classification</span><select class="v34-select"><option>Professional / institutional</option><option>Retail</option></select></label><label class="v34-field"><span>Risk profile</span><select class="v34-select"><option>Balanced growth</option><option>Conservative</option><option>Growth</option></select></label><label class="v34-field"><span>Horizon</span><select class="v34-select"><option>5+ years</option><option>3–5 years</option></select></label><label class="v34-field"><span>Liquidity need</span><select class="v34-select"><option>Quarterly or less</option><option>Monthly</option></select></label><label class="v34-field"><span>Loss capacity</span><select class="v34-select"><option>Moderate</option><option>Low</option><option>High</option></select></label><label class="v34-field"><span>Knowledge / experience</span><select class="v34-select"><option>Institutional / experienced</option><option>Requires advice</option></select></label></div></div></section><aside class="v34-card v34-span-5"><div class="v34-card-head"><div><div class="v34-kicker">DIGITISED MANDATE</div><h2>${esc(c.mandate)}</h2></div></div><div class="v34-card-body"><div class="v34-list"><div class="v34-row"><span><strong>Single issuer</strong><small>Hard limit</small></span><em>10%</em></div><div class="v34-row"><span><strong>Equities</strong><small>Approved band</small></span><em>30–65%</em></div><div class="v34-row"><span><strong>Private assets</strong><small>Maximum</small></span><em>20%</em></div><div class="v34-row"><span><strong>Offshore</strong><small>Permission</small></span><em>Within mandate</em></div></div></div></aside></div>`;
  } else {
    h.innerHTML=`<div class="v34-grid"><section class="v34-card v34-span-7"><div class="v34-card-head"><div><div class="v34-kicker">HUMAN DECISION</div><h2>Approve, request information or decline</h2><p>Automation can package evidence and screening; it does not make the final KYC decision.</p></div></div><div class="v34-card-body"><label class="v34-field"><span>Decision rationale *</span><textarea class="v34-textarea" id="v34KycDecisionReason" placeholder="Evidence reviewed, exceptions considered and basis for decision."></textarea></label><div style="display:flex;gap:7px;flex-wrap:wrap;margin-top:9px"><button class="v34-btn" id="v34KycRequest">Request information</button><button class="v34-btn danger" id="v34KycDecline">Decline</button><button class="v34-btn primary" id="v34KycApprove" ${c.blockers?'disabled':''}>Approve & activate</button></div></div></section><aside class="v34-card v34-span-5"><div class="v34-card-head"><div><div class="v34-kicker">AUDIT</div><h2>Decision evidence</h2></div></div><div class="v34-card-body"><div class="v34-list"><div class="v34-row"><span><strong>Screening run</strong><small>${esc(c.screenRef)}</small></span><em>${esc(c.screened)}</em></div><div class="v34-row"><span><strong>Evidence completeness</strong></span><em>${c.evidence.filter(e=>e[3]==='Missing').length?'Open':'Complete'}</em></div><div class="v34-row"><span><strong>Mandate</strong></span><em>${esc(c.mandate)}</em></div><div class="v34-row"><span><strong>Decision</strong></span><em>${esc(c.decision)}</em></div></div></div></aside></div>`;
    $('#v34KycRequest')?.addEventListener('click',()=>notify('Information request created','The case remains open and the request is retained in the audit timeline.'));
    $('#v34KycDecline')?.addEventListener('click',()=>notify('Decision requires rationale','Enter the decline rationale and confirm using the controlled decision workflow.','warn'));
    $('#v34KycApprove')?.addEventListener('click',()=>{const text=$('#v34KycDecisionReason').value.trim();if(!text)return notify('Rationale required','Compliance must record the basis for approval.','error');c.decision='Approved';c.status='Ready';c.readiness=100;c.stage=6;notify('KYC approved','The client is ready for controlled account / mandate activation.');renderKycQueue();renderKycDetail()});
  }
}
function buildKyc(){const page=$('#page-onboarding');if(!page)return;page.innerHTML=`<div class="v33-shell"><header class="v33-head"><div><div class="v33-eyebrow">APPLICATION → OWNERSHIP → IDENTITY → FINANCIAL CRIME → SUITABILITY → MANDATE → APPROVAL</div><h1>Onboarding & KYC</h1><p>Review one client case end to end. Evidence source, screening provider/run, risk factors, mandate controls and the final human decision are visible in the same workspace.</p></div><div class="v33-actions"><button class="v33-btn" id="v34KycPublic">Applicant experience</button><button class="v33-btn" id="v34KycExport">Export case pack</button><button class="v33-btn primary" id="v34KycNew">+ Client</button></div></header><div class="v34-kpis"><article class="v34-kpi"><span>Open cases</span><strong>${kycCases.filter(x=>x.status!=='Ready').length}</strong><small>Exception-led review queue</small></article><article class="v34-kpi"><span>Ready to activate</span><strong>${kycCases.filter(x=>x.status==='Ready').length}</strong><small>All hard controls passed</small></article><article class="v34-kpi"><span>High risk / EDD</span><strong>${kycCases.filter(x=>x.risk==='High').length}</strong><small>Human enhanced review</small></article><article class="v34-kpi"><span>Evidence missing</span><strong>${kycCases.reduce((a,c)=>a+c.evidence.filter(e=>e[3]==='Missing').length,0)}</strong><small>Explicit document gaps</small></article><article class="v34-kpi"><span>Screening traceability</span><strong>${kycCases.filter(x=>x.screenRef!=='—').length}/${kycCases.length}</strong><small>Provider + run reference</small></article><article class="v34-kpi"><span>Final authority</span><strong>Human</strong><small>Compliance approval required</small></article></div><div class="v34-kyc-layout"><aside class="v34-card"><div class="v34-card-head"><div><div class="v34-kicker">CASE QUEUE</div><h2>What needs action</h2></div></div><div class="v34-card-body"><div class="v34-search"><input id="v34KycSearch" placeholder="Search client, ref or owner"></div><select class="v34-select" id="v34KycFilter" style="margin-top:7px"><option value="action">Needs action</option><option value="all">All cases</option><option value="ready">Ready</option><option value="high">High risk</option></select></div><div class="v34-kyc-queue" id="v34KycQueue"></div></aside><main class="v34-card" id="v34KycDetail"></main></div></div>`;renderKycQueue();renderKycDetail();$('#v34KycSearch').oninput=e=>{kycQuery=e.target.value.toLowerCase();renderKycQueue()};$('#v34KycFilter').onchange=e=>{kycFilter=e.target.value;renderKycQueue();renderKycDetail()};$('#v34KycPublic').onclick=()=>{try{window.open('public-onboarding.html','_blank')}catch(e){notify('Applicant experience','Open public-onboarding.html from the deployment folder.')}};$('#v34KycExport').onclick=()=>notify('KYC case pack prepared','Production export would include evidence manifest, screening references, decisions and audit events.');$('#v34KycNew').onclick=()=>{try{window.open('public-onboarding.html','_blank')}catch(e){}}}

