let modelRows=[
{id:'MOD-RISK-01',name:'Multi-asset risk model',purpose:'VaR / stress / risk budget',version:'3.8',owner:'Risk Analytics',validation:'2026-11-30',state:'Production',risk:'High'},
{id:'MOD-VAL-04',name:'Private asset valuation model',purpose:'Quarterly fair value',version:'2.4',owner:'Valuation',validation:'2026-09-18',state:'Production',risk:'High'},
{id:'MOD-OPT-02',name:'Portfolio optimiser',purpose:'Target portfolio construction',version:'1.9',owner:'Quant Research',validation:'2026-10-14',state:'Validated',risk:'Medium'},
{id:'MOD-TCA-03',name:'Transaction cost estimator',purpose:'Pre-trade cost / liquidity',version:'2.1',owner:'Trading Analytics',validation:'2026-09-06',state:'Review',risk:'Medium'}
];
let modelSelected='MOD-OPT-02',modelStage=0,modelDraft=safeStore.get('matanho-v34-model-draft',{})||{};
const modelStages=[['Purpose','Use & materiality'],['Data','Lineage & fields'],['Method','Code & assumptions'],['Testing','Metrics & thresholds'],['Validation','Independent review'],['Approval','Committee & limits'],['Monitor','Deploy & drift']];
function md(k,d=''){return modelDraft[k]??d}function syncModel(root){$$('[data-md]',root).forEach(el=>modelDraft[el.dataset.md]=el.value);safeStore.set('matanho-v34-model-draft',modelDraft)}
function modelStageHtml(i){if(i===0)return `<div class="v34-form"><label class="v34-field v34-wide"><span>Model name *</span><input class="v34-input" data-md="name" value="${esc(md('name'))}" placeholder="Specific governed model name"></label><label class="v34-field"><span>Model class</span><select class="v34-select" data-md="class"><option>Risk</option><option>Valuation</option><option>Optimisation</option><option>Execution / TCA</option><option>AI / ML</option><option>Financial crime</option></select></label><label class="v34-field"><span>Risk / materiality tier</span><select class="v34-select" data-md="tier"><option>High</option><option selected>Medium</option><option>Low</option></select></label><label class="v34-field"><span>Business owner *</span><input class="v34-input" data-md="businessOwner" value="${esc(md('businessOwner','Investment Office'))}"></label><label class="v34-field"><span>Technical owner *</span><input class="v34-input" data-md="technicalOwner" value="${esc(md('technicalOwner','Quant Research'))}"></label><label class="v34-field v34-wide"><span>Purpose / decision influenced *</span><textarea class="v34-textarea" data-md="purpose" placeholder="What decision, calculation or output may this model influence?">${esc(md('purpose'))}</textarea></label><label class="v34-field v34-wide"><span>Permitted use</span><textarea class="v34-textarea" data-md="permitted" placeholder="Approved contexts, portfolios and users">${esc(md('permitted'))}</textarea></label><label class="v34-field v34-wide"><span>Prohibited use / authority boundary</span><textarea class="v34-textarea" data-md="prohibited" placeholder="What the model must never decide or approve autonomously">${esc(md('prohibited'))}</textarea></label></div>`;
if(i===1)return `<div class="v34-form"><label class="v34-field"><span>Governed data product *</span><input class="v34-input" data-md="dataset" value="${esc(md('dataset','Whole Portfolio Positions'))}"></label><label class="v34-field"><span>Dataset owner</span><input class="v34-input" data-md="dataOwner" value="${esc(md('dataOwner','Data Office'))}"></label><label class="v34-field"><span>Snapshot / version *</span><input class="v34-input" data-md="snapshot" value="${esc(md('snapshot','2026-08-31T15:30:00Z'))}"></label><label class="v34-field"><span>Data classification</span><select class="v34-select" data-md="classification"><option>Internal</option><option>Confidential</option><option>Restricted personal data</option></select></label><label class="v34-field v34-wide"><span>Feature / field specification *</span><textarea class="v34-textarea" data-md="features">${esc(md('features','Security ID, market value, returns, factor exposures, price history, liquidity score'))}</textarea></label><label class="v34-field v34-wide"><span>Lineage / upstream sources</span><textarea class="v34-textarea" data-md="lineage" placeholder="IBOR snapshot → market data → feature pipeline → model dataset">${esc(md('lineage'))}</textarea></label><label class="v34-field"><span>Training / calibration window</span><input class="v34-input" data-md="trainWindow" value="${esc(md('trainWindow','2021-01-01 to 2026-06-30'))}"></label><label class="v34-field"><span>Validation / holdout window</span><input class="v34-input" data-md="holdout" value="${esc(md('holdout','2026-07-01 to 2026-08-31'))}"></label><label class="v34-field v34-wide"><span>Missing data / outlier policy</span><textarea class="v34-textarea" data-md="missing">${esc(md('missing','Reject stale prices over threshold; approved imputation only for documented fields.'))}</textarea></label></div>`;
if(i===2)return `<div class="v34-form"><label class="v34-field"><span>Algorithm / method *</span><input class="v34-input" data-md="algorithm" value="${esc(md('algorithm'))}" placeholder="Historical simulation / optimisation / gradient boosting…"></label><label class="v34-field"><span>Code repository / commit *</span><input class="v34-input" data-md="repo" value="${esc(md('repo','git:quant/models@d9a84f1'))}"></label><label class="v34-field v34-wide"><span>Methodology *</span><textarea class="v34-textarea" style="min-height:120px" data-md="method" placeholder="Formula, architecture, calibration, objective function, constraints and fallback method.">${esc(md('method'))}</textarea></label><label class="v34-field v34-wide"><span>Key assumptions *</span><textarea class="v34-textarea" data-md="assumptions" placeholder="Distribution, liquidity, stationarity, regime, valuation or behavioural assumptions">${esc(md('assumptions'))}</textarea></label><label class="v34-field v34-wide"><span>Known limitations</span><textarea class="v34-textarea" data-md="limitations" placeholder="Where the model is weak, out-of-scope or unreliable">${esc(md('limitations'))}</textarea></label><label class="v34-field"><span>Benchmark / challenger</span><input class="v34-input" data-md="challenger" value="${esc(md('challenger','Current production model'))}"></label><label class="v34-field"><span>Fallback / manual method</span><input class="v34-input" data-md="fallback" value="${esc(md('fallback','Last approved production version'))}"></label></div>`;
if(i===3)return `<div><div class="v34-help" style="margin-bottom:9px">Define tests with an explicit pass threshold. “Backtest required” alone is not enough to govern a model.</div>${[['Unit / integration tests','Coverage %','95'],['Backtest / out-of-sample','Primary metric','0.75'],['Stress / sensitivity','Max instability %','10'],['Challenger comparison','Improvement bps','5']].map((x,n)=>`<div class="v34-test-row"><strong>${x[0]}</strong><label class="v34-field"><span>${x[1]}</span><input class="v34-input" data-md="testMetric${n}" value="${esc(md('testMetric'+n,x[2]))}"></label><label class="v34-field"><span>Result</span><select class="v34-select" data-md="testResult${n}"><option>Pending</option><option>Pass</option><option>Fail</option></select></label></div>`).join('')}<label class="v34-field"><span>Test evidence / notebook / run reference</span><input class="v34-input" data-md="testEvidence" value="${esc(md('testEvidence'))}" placeholder="TEST-RUN-2026-..."></label>${md('class')==='AI / ML'?`<div class="v34-form" style="margin-top:9px"><label class="v34-field"><span>Bias / fairness test</span><input class="v34-input" data-md="fairness" placeholder="Metric + threshold"></label><label class="v34-field"><span>Explainability method</span><input class="v34-input" data-md="explainability" placeholder="SHAP / reason codes / rule trace"></label></div>`:''}</div>`;
if(i===4)return `<div class="v34-form"><label class="v34-field"><span>Independent validator *</span><input class="v34-input" data-md="validator" value="${esc(md('validator'))}" placeholder="Cannot be the model developer"></label><label class="v34-field"><span>Validation due</span><input class="v34-input" type="date" data-md="validationDue" value="${esc(md('validationDue','2026-09-30'))}"></label><label class="v34-field v34-wide"><span>Validation scope</span><textarea class="v34-textarea" data-md="validationScope" placeholder="Conceptual soundness, data, implementation, outcomes, limitations…">${esc(md('validationScope'))}</textarea></label><label class="v34-field v34-wide"><span>Findings and severity</span><textarea class="v34-textarea" data-md="findings" placeholder="Finding · severity · owner · due date · closure evidence">${esc(md('findings'))}</textarea></label><label class="v34-field"><span>Validation conclusion</span><select class="v34-select" data-md="validationConclusion"><option>Pending</option><option>Approved</option><option>Approved with conditions</option><option>Rejected</option></select></label><label class="v34-field"><span>Validation evidence reference</span><input class="v34-input" data-md="validationRef" value="${esc(md('validationRef'))}"></label></div>`;
if(i===5)return `<div class="v34-form"><label class="v34-field"><span>Approving committee *</span><select class="v34-select" data-md="committee"><option>Model Risk Committee</option><option>Investment Committee</option><option>Valuation Committee</option></select></label><label class="v34-field"><span>Decision date</span><input class="v34-input" type="date" data-md="decisionDate"></label><label class="v34-field"><span>Approved version</span><input class="v34-input" data-md="approvedVersion" placeholder="v1.0.0"></label><label class="v34-field"><span>Effective date</span><input class="v34-input" type="date" data-md="effectiveDate"></label><label class="v34-field v34-wide"><span>Conditions / limits of approval</span><textarea class="v34-textarea" data-md="approvalLimits" placeholder="Portfolios, use cases, thresholds, expiry or human-review requirements">${esc(md('approvalLimits'))}</textarea></label><label class="v34-field v34-wide"><span>Committee minute / approval reference</span><input class="v34-input" data-md="approvalRef" value="${esc(md('approvalRef'))}" placeholder="MRC-2026-..."></label></div>`;
return `<div class="v34-form"><label class="v34-field"><span>Deployment environment</span><select class="v34-select" data-md="environment"><option>Production</option><option>Shadow / challenger</option><option>Sandbox</option></select></label><label class="v34-field"><span>Production package / image</span><input class="v34-input" data-md="artifact" value="${esc(md('artifact'))}" placeholder="model://registry/name/version"></label><label class="v34-field"><span>Monitoring frequency</span><select class="v34-select" data-md="monitorFreq"><option>Daily</option><option>Weekly</option><option>Monthly</option><option>Quarterly</option></select></label><label class="v34-field"><span>Retrain / recalibrate cadence</span><input class="v34-input" data-md="retrain" value="${esc(md('retrain','Quarterly or trigger-based'))}"></label><label class="v34-field v34-wide"><span>Monitoring metrics and trigger thresholds *</span><textarea class="v34-textarea" data-md="monitoring" placeholder="Drift, error, stability, performance, exceptions; threshold and owner per metric">${esc(md('monitoring'))}</textarea></label><label class="v34-field"><span>Rollback version</span><input class="v34-input" data-md="rollback" value="${esc(md('rollback','Previous approved version'))}"></label><label class="v34-field"><span>Incident owner</span><input class="v34-input" data-md="incidentOwner" value="${esc(md('incidentOwner','Model Risk'))}"></label><label class="v34-field v34-wide"><span>Change / decommission policy</span><textarea class="v34-textarea" data-md="changePolicy">${esc(md('changePolicy','Material changes require impact assessment, revalidation and committee approval.'))}</textarea></label></div>`}
function renderModelRegistry(){const h=$('#v34ModelRegistry');if(!h)return;const q=$('#v34ModelSearch')?.value.toLowerCase()||'';h.innerHTML=modelRows.filter(m=>!q||Object.values(m).join(' ').toLowerCase().includes(q)).map(m=>`<div class="v34-model-item ${m.id===modelSelected?'active':''}" data-model-id="${m.id}"><span><strong>${esc(m.name)}</strong><small>${m.id} · ${esc(m.purpose)} · ${esc(m.owner)}</small></span><span class="v34-chip ${m.state==='Production'?'good':m.state==='Review'?'warn':'blue'}">${esc(m.state)}</span></div>`).join('');$$('[data-model-id]',h).forEach(x=>x.onclick=()=>{modelSelected=x.dataset.modelId;renderModelRegistry();const m=modelRows.find(y=>y.id===modelSelected);notify('Model selected',`${m.id} · ${m.version} · validation ${m.validation}`)})}
function renderModelBuilder(){const h=$('#v34ModelBuilder');if(!h)return;h.innerHTML=`<div class="v34-model-stagebar">${modelStages.map((s,i)=>`<button class="${i<modelStage?'done':i===modelStage?'active':''}" data-model-stage="${i}"><span>0${i+1}</span><strong>${s[0]}</strong></button>`).join('')}</div><div class="v34-card" style="margin-top:10px"><div class="v34-card-head"><div><div class="v34-kicker">${modelStages[modelStage][0].toUpperCase()}</div><h2>${modelStages[modelStage][1]}</h2><p>Capture information that an independent validator and approver can actually use.</p></div></div><div class="v34-card-body" id="v34ModelStagePane">${modelStageHtml(modelStage)}<div class="v34-model-footer"><span class="v34-help">Draft persists between stages.</span><div><button class="v34-btn" id="v34ModelSave">Save draft</button><button class="v34-btn" id="v34ModelBack" ${modelStage===0?'disabled':''}>Back</button><button class="v34-btn primary" id="v34ModelNext">${modelStage===6?'Register governed model':'Continue'}</button></div></div></div></div>`;$$('[data-model-stage]',h).forEach(b=>b.onclick=()=>{syncModel(h);modelStage=+b.dataset.modelStage;renderModelBuilder()});$('#v34ModelSave').onclick=()=>{syncModel(h);notify('Model draft saved','Definition, data, method and governance evidence retained.')};$('#v34ModelBack').onclick=()=>{syncModel(h);modelStage=Math.max(0,modelStage-1);renderModelBuilder()};$('#v34ModelNext').onclick=()=>{syncModel(h);if(modelStage===0&&(!md('name')||!md('businessOwner')||!md('technicalOwner')||!md('purpose')))return notify('Definition incomplete','Name, owners and purpose are required.','error');if(modelStage===1&&(!md('dataset')||!md('snapshot')||!md('features')))return notify('Dataset incomplete','Data product, snapshot and feature specification are required.','error');if(modelStage===2&&(!md('algorithm')||!md('repo')||!md('method')||!md('assumptions')))return notify('Method incomplete','Algorithm, code version, methodology and assumptions are required.','error');if(modelStage<6){modelStage++;renderModelBuilder();return}const foundation=[['name','model name'],['businessOwner','business owner'],['technicalOwner','technical owner'],['purpose','purpose'],['dataset','governed dataset'],['snapshot','dataset snapshot'],['features','feature specification'],['algorithm','algorithm / method'],['repo','code version'],['method','methodology'],['assumptions','assumptions']];const missing=foundation.filter(([k])=>!String(md(k)||'').trim()).map(x=>x[1]);if(missing.length)return notify('Model record incomplete',`Complete: ${missing.join(', ')}.`,'error');if(!md('monitoring'))return notify('Monitoring controls required','Define production metrics and trigger thresholds before registration.','error');const id=`MOD-${String(modelRows.length+5).padStart(2,'0')}`,name=md('name');modelRows.unshift({id,name,purpose:md('purpose').slice(0,38),version:md('approvedVersion')||'Draft',owner:md('businessOwner'),validation:md('validationDue')||'Pending',state:'Draft',risk:md('tier','Medium')});modelDraft={};safeStore.set('matanho-v34-model-draft',modelDraft);modelStage=0;modelSelected=id;notify('Governed model registered',`${name} was added in Draft state; independent validation and approval remain required.`);renderModelRegistry();renderModelBuilder()}}
function buildModels(){const page=$('#page-model-governance');if(!page)return;page.innerHTML=`<div class="v33-shell"><header class="v33-head"><div><div class="v33-eyebrow">PURPOSE → DATA LINEAGE → METHOD → TESTING → VALIDATION → APPROVAL → MONITORING</div><h1>Model Governance</h1><p>A model record is not a name and a textarea. The build captures owners, permitted use, data lineage, code version, assumptions, measurable tests, independent validation, approval conditions and production monitoring.</p></div><div class="v33-actions"><button class="v33-btn" id="v34ModelCalendar">Validation calendar</button><button class="v33-btn primary" id="v34NewModel">+ New model</button></div></header><div class="v34-kpis"><article class="v34-kpi"><span>Registered</span><strong>${modelRows.length}</strong><small>Governed demo registry</small></article><article class="v34-kpi"><span>Production</span><strong>${modelRows.filter(x=>x.state==='Production').length}</strong><small>Approved versions only</small></article><article class="v34-kpi"><span>Due validation</span><strong>2</strong><small>Next 30 days</small></article><article class="v34-kpi"><span>Open findings</span><strong>7</strong><small>2 high severity</small></article><article class="v34-kpi"><span>Drift alerts</span><strong>2</strong><small>1 under investigation</small></article><article class="v34-kpi"><span>Unapproved use</span><strong>0</strong><small>Policy enforced</small></article></div><div class="v34-model-layout"><aside class="v34-card"><div class="v34-card-head"><div><div class="v34-kicker">MODEL REGISTRY</div><h2>Governed assets</h2></div></div><div class="v34-card-body"><div class="v34-search"><input id="v34ModelSearch" placeholder="Search model, purpose or owner"></div></div><div class="v34-model-registry" id="v34ModelRegistry"></div></aside><main id="v34ModelBuilder"></main></div></div>`;renderModelRegistry();renderModelBuilder();$('#v34ModelSearch').oninput=renderModelRegistry;$('#v34NewModel').onclick=()=>{modelDraft={};modelStage=0;renderModelBuilder();$('#v34ModelStagePane input')?.focus()};$('#v34ModelCalendar').onclick=()=>notify('Validation calendar','Private asset valuation model is due 18 Sep; transaction cost estimator is due 06 Sep.')}

